const D = (n) => { try { const r = $(n).first().json; return r && r.data !== undefined ? r.data : r; } catch (e) { return null; } };
const V = (m) => (m && typeof m === 'object' && 'value' in m) ? m.value : m;
const est = (m) => (m && typeof m === 'object' && m.confidence && m.confidence !== 'confirmed') ? ' (تقديري)' : '';
const money = (v) => (v === null || v === undefined || v === '') ? '—' : Number(v).toLocaleString('en-US', { maximumFractionDigits: 0 }) + ' ج.م';
const num = (v) => (v === null || v === undefined || v === '') ? '—' : Number(v).toLocaleString('en-US', { maximumFractionDigits: 1 });
const pct = (v) => (v === null || v === undefined || v === '') ? '—' : Number(v).toFixed(1) + '%';
const short = (v, n = 90) => { const s = typeof v === 'string' ? v : JSON.stringify(v); return s && s.length > n ? s.slice(0, n - 1) + '…' : (s || ''); };
const list = (a, f, max = 5) => (a || []).slice(0, max).map((x, i) => (i + 1) + ') ' + f(x)).join('\n');
